package yagen.waitmydawn.kb.service;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.util.*;import yagen.waitmydawn.kb.model.*;import yagen.waitmydawn.kb.dto.QaMetrics;
class MediaAuditTest {
 @TempDir Path temp;
 AnswerArtifacts artifacts(String role,boolean available)throws Exception {var image=new java.awt.image.BufferedImage(32,32,2);image.setRGB(4,4,0xff55ff66);var bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",bytes);var asset=new ImageAssetStore(temp).put(bytes.toByteArray());if(!available)Files.delete(new ImageAssetStore(temp).resolve(asset.id(),asset.relativePath()));var picture=new AnswerArtifacts.Picture("e1",asset.id(),asset.relativePath(),"实体",null,role,List.of(),"状态键：default");return new AnswerArtifacts(null,null,List.of(),List.of(picture));}
 @Test void entityMetadataIsAuditedWithoutBeingClassifiedAsAnUnboundDocumentImage()throws Exception{var a=artifacts("ENTITY",true);var report=MediaAudit.capture("实体外观","![图](kb-image:e1)",a,temp,null);assertEquals(1,report.availability().valid());assertTrue(report.pictures().getFirst().displayed());assertEquals("ENTITY_STATE_METADATA",report.pictures().getFirst().provenance());assertEquals(0,report.documentGrounding().displayed());}
 @Test void documentImagesStillRequireGroundingAndMissingFilesAreVisibleInAudit()throws Exception{var a=artifacts("ILLUSTRATION",false);var report=MediaAudit.capture("教程","![图](kb-image:e1)",a,temp,null);assertFalse(report.pictures().getFirst().available());assertEquals(1,report.documentGrounding().unbound());assertEquals("UNBOUND",report.pictures().getFirst().provenance());}
 @Test void codeFenceReferencesDoNotCountAsDisplayedImages()throws Exception{var report=MediaAudit.capture("实体","```\n![图](kb-image:e1)\n```",artifacts("ENTITY",true),temp,null);assertFalse(report.pictures().getFirst().displayed());}
 @Test void boundedTraceAlwaysRetainsSelectedCandidate(){var trail=new MediaAudit.Trail("profile");var json=new com.fasterxml.jackson.databind.ObjectMapper();for(int i=0;i<520;i++)trail.record(json.createObjectNode().put("id","demo:mob").put("stateKey","s"+i),"EXCLUDED","STATE_MISMATCH");trail.record(json.createObjectNode().put("id","demo:mob").put("stateKey","selected"),"SELECTED","REGISTRY_AND_STATE_MATCH");assertEquals(512,trail.snapshot().candidates().size());assertTrue(trail.snapshot().truncated());assertTrue(trail.snapshot().candidates().stream().anyMatch(c->c.decision().equals("SELECTED")));}
 @Test void metricsRoundTripPreservesFinalMediaAudit()throws Exception{var m=new QaMetrics();m.mediaAudit=MediaAudit.capture("实体","![图](kb-image:e1)",artifacts("ENTITY",true),temp,null);var history=new MetricsHistoryService(temp);history.save(m);var rows=history.loadAll();assertEquals(1,rows.size());assertEquals(1,rows.getFirst().mediaAudit.availability().valid());assertTrue(rows.getFirst().toUiSummary().contains("最终配图"));}
 @Test void requestedExplicitStateIsRetainedEvenWhenNoCandidateSupportsIt(){var trail=new MediaAudit.Trail("profile","growth_stage=99 sex=male");assertEquals("99",trail.snapshot().requestedAxes().get("growth_stage"));assertEquals("male",trail.snapshot().requestedAxes().get("sex"));}
}
